// ViewChild: access a child component or DOM element
@Component({ template: `<canvas #myCanvas></canvas>` })
export class ChartComponent implements AfterViewInit {
  @ViewChild('myCanvas') canvasRef!: ElementRef<HTMLCanvasElement>;

  ngAfterViewInit() {
    // Safe to access DOM here — view is rendered
    const ctx = this.canvasRef.nativeElement.getContext('2d');
  }
}

// Dynamic component loading
@Component({ template: `<ng-container #host></ng-container>` })
export class ModalHostComponent {
  @ViewChild('host', { read: ViewContainerRef }) host!: ViewContainerRef;

  open<T>(component: Type<T>, inputs?: Partial<T>) {
    this.host.clear();
    const ref = this.host.createComponent(component);
    if (inputs) Object.assign(ref.instance as object, inputs);
  }
}

